WITH monthly_gender_stats AS ( SELECT d.d_year, d.d_moy AS month, cd.cd_gender, SUM(cr.cr_net_loss) AS total_net_loss, AVG(cr.cr_return_quantity) AS avg_return_qty, COUNT(DISTINCT c.c_customer_sk) AS distinct_customers, SUM(cr.cr_return_amount) AS total_return_amount FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk JOIN customer c ON cr.cr_returning_customer_sk = c.c_customer_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE d.d_year = 2020 AND cr.cr_store_credit > 100 GROUP BY d.d_year, d.d_moy, cd.cd_gender ) SELECT d_year, month, cd_gender, total_net_loss, avg_return_qty, distinct_customers, total_return_amount, RANK() OVER (PARTITION BY cd_gender ORDER BY total_net_loss DESC) AS net_loss_rank FROM monthly_gender_stats ORDER BY cd_gender, net_loss_rank
